// Client-side filtering for hub/insights.html (generated by scripts/build_insights.py).
// Filters: free-text search, topic, evidence kind, tag chips (any selected tag matches).
(() => {
  const q = document.getElementById("ins-q");
  if (!q) return; // empty-state page has no filters

  const topicSel = document.getElementById("ins-topic");
  const kindSel = document.getElementById("ins-kind");
  const chips = [...document.querySelectorAll(".tag-chip")];
  const visibleCount = document.getElementById("ins-visible");
  const selected = new Set();

  const matches = (el, countKind) => {
    const text = q.value.trim().toLowerCase();
    const topic = topicSel.value;
    const kind = kindSel.value;
    const tags = (el.dataset.tags || "").split(",").filter(Boolean);
    if (text && !(el.dataset.search || "").includes(text)) return false;
    if (topic && el.dataset.topic !== topic) return false;
    if (countKind && kind && !(el.dataset.kinds || "").split(" ").includes(kind)) return false;
    if (selected.size && !tags.some((t) => selected.has(t))) return false;
    return true;
  };

  function apply() {
    // Full cards (by topic) drive the visible counter; compact items mirror the same filter.
    let shown = 0;
    document.querySelectorAll(".ins-card").forEach((el) => {
      const ok = matches(el, true);
      el.hidden = !ok;
      if (ok) shown += 1;
    });
    document.querySelectorAll(".ins-item").forEach((el) => { el.hidden = !matches(el, true); });
    document.querySelectorAll(".dive-table tbody tr").forEach((el) => { el.hidden = !matches(el, false); });
    document.querySelectorAll(".tag-group, .topic-group").forEach((group) => {
      group.hidden = !group.querySelector(".ins-item:not([hidden]), .ins-card:not([hidden])");
    });
    if (visibleCount) visibleCount.textContent = String(shown);
  }

  chips.forEach((chip) => {
    chip.addEventListener("click", () => {
      const tag = chip.dataset.tag;
      if (selected.has(tag)) selected.delete(tag); else selected.add(tag);
      chip.classList.toggle("active", selected.has(tag));
      chip.setAttribute("aria-pressed", String(selected.has(tag)));
      apply();
    });
  });
  [q, topicSel, kindSel].forEach((el) => el.addEventListener("input", apply));

  // Deep link: hub/insights.html?tag=kafka or #tag-kafka preselects a tag.
  const pre = new URLSearchParams(location.search).get("tag");
  if (pre) chips.filter((c) => c.dataset.tag === pre).forEach((c) => c.click());
  apply();
})();
